/** Dezelfde sterretjes als bij de muisvolger en elders op de site: [midden x, midden y, grootte]. */
const STAR = "M12 0c.6 6.4 5.6 11.4 12 12-6.4.6-11.4 5.6-12 12-.6-6.4-5.6-11.4-12-12C6.4 11.4 11.4 6.4 12 0Z";
const STARS: [number, number, number][] = [
  [354.5, 174.5, 60],
  [392, 232, 29],
  [77.5, 310, 38],
];
function starTransform([x, y, size]: [number, number, number]) {
  return `translate(${x - size / 2} ${y - size / 2}) scale(${size / 24})`;
}

function Glasses() {
  return (
    <>
      <path d={GLASS_DARK} fill="currentColor" fillRule="evenodd" />
      <path d={WINE} style={ACCENT} fillRule="evenodd" />
    </>
  );
}

function Stars() {
  return (
    <g style={ACCENT}>
      {STARS.map((s) => (
        <path key={`${s[0]}-${s[1]}`} d={STAR} transform={starTransform(s)} />
      ))}
    </g>
  );
}

type Props = { className?: string; title?: string };

/** Beeldmerk met de tekst ernaast. */
export function WineLogo({ className = "", title = "Proost Mee" }: Props) {
  return (
    <svg viewBox="54 142 1135 266" role="img" aria-label={title} className={className}>
      <Glasses />
      <Stars />
      <path d={TEXT_TOP} fill="currentColor" fillRule="evenodd" />
      <path d={TEXT_BOTTOM} fill="currentColor" fillRule="evenodd" />
    </svg>
  );
}

/** Beeldmerk met de tekst eronder (backoffice): PROOST en MEE gecentreerd onder het beeldmerk. */
export function WineLogoStacked({ className = "", title = "Proost Mee" }: Props) {
  return (
    <svg viewBox="462 142 724 530" role="img" aria-label={title} className={className}>
      <g transform="translate(591 0)">
        <Glasses />
        <Stars />
      </g>
      <path d={TEXT_TOP} fill="currentColor" fillRule="evenodd" transform="translate(0 271)" />
      <path d={TEXT_BOTTOM} fill="currentColor" fillRule="evenodd" transform="translate(176.5 271)" />
    </svg>
  );
}

/**
 * Laadanimatie: de twee glazen zwaaien tegen elkaar aan, de wijn schommelt mee, er springt een vonk,
 * de sterretjes ploppen op en de naam schuift eronder in beeld. Het beeldmerk is in het midden gesneden
 * (clipPath) zodat elk glas om zijn eigen voet kan kantelen; de animatie zelf staat in globals.css.
 */
export function ClinkMark({ className = "" }: { className?: string }) {
  // Elk glas draait om zijn voet: translate naar het draaipunt, draai, en weer terug.
  const glass = (clip: string, cls: string, px: number, py: number) => (
    <g transform={`translate(${px} ${py})`}>
      <g className={cls}>
        <g transform={`translate(${-px} ${-py})`}>
          <g clipPath={`url(#${clip})`}>
            <path d={GLASS_DARK} fill="currentColor" fillRule="evenodd" />
            <g className="clink-wine">
              <path d={WINE} style={ACCENT} fillRule="evenodd" />
            </g>
          </g>
        </g>
      </g>
    </g>
  );
  const rays = [-70, -35, 0, 35, 70];
  return (
    <svg viewBox="0 0 724 530" aria-hidden className={className}>
      <defs>
        <clipPath id="clink-left">
          <rect x="0" y="0" width="232" height="540" />
        </clipPath>
        <clipPath id="clink-right">
          <rect x="232" y="0" width="200" height="540" />
        </clipPath>
      </defs>
      <g transform="translate(-462 -142)">
        <g transform="translate(591 0)">
          {glass("clink-left", "clink-l", 135, 388)}
          {glass("clink-right", "clink-r", 318, 374)}
          <g transform="translate(232 206)">
            <g className="clink-burst" style={ACCENT}>
              {rays.map((a) => (
                <rect key={a} x="-1.5" y="-62" width="3" height="20" rx="1.5" transform={`rotate(${a})`} fill="currentColor" style={ACCENT} />
              ))}
            </g>
          </g>
          {STARS.map((s, i) => (
            <g key={i} transform={starTransform(s)}>
              <path d={STAR} className={`clink-star clink-star-${i}`} style={ACCENT} />
            </g>
          ))}
        </g>
        <g transform="translate(0 271)">
          <path d={TEXT_TOP} className="clink-word clink-word-1" fill="currentColor" fillRule="evenodd" />
        </g>
        <g transform="translate(176.5 271)">
          <path d={TEXT_BOTTOM} className="clink-word clink-word-2" fill="currentColor" fillRule="evenodd" />
        </g>
      </g>
    </svg>
  );
}
